     * resolution.already_resolved, resolution.bad_action, resolution.chain_ambiguous,
     * resolution.disabled, resolution.network_required, resolution.not_underpaid,
     * resolution.unsupported_network, treasury.no_ccy_map, wallet.static_not_found
     *
     * @param ResolveRequest|array{
     *     action: string,
     *     address?: string,
     *     network?: string,
     *     order_id?: string,
     *     reference?: string,
     *     uuid?: string
     * } $params
     *
     * @return ResolveRefundResult|ResolveAcceptResult|array<string, mixed>
     */
    public function resolve(
        ResolveRequest|array $params,
        ?RequestOptions $options = null,
    ): ResolveRefundResult|ResolveAcceptResult|array {
        return $this->request(
            Routes::get('resolvePayment'),
            Wire::body($params),
            $options,
            parse: ResolveResult::parse(...),
        );
    }
}
